def _stage(path: Path, document: Mapping[str, object]) -> str:
    try:
        return stage_private_json(str(path), document)
    except OSError as e:
        raise ClaudeSettingsError(f"Could not write {path}: {e}") from e

def _land(
    path: Path,
    staged: str | None,
    also_discard: Sequence[str | None] = (),
    commit: Callable[[str, str], None] = commit_staged_json,
) -> None:
    """Commit a staged file to `path`, or remove `path` when nothing is staged for it. The one place a
    filesystem error becomes a ClaudeSettingsError; on failure the operation's other staged files are
    discarded, so no temp file holding a token is left behind."""
    try:
        if staged is None:
            path.unlink(missing_ok=True)
        else:
            commit(staged, str(path))
    except OSError as e:
        for other in also_discard:
            if other is not None:
                discard_staged_json(other)
        raise ClaudeSettingsError(f"Could not {'remove' if staged is None else 'write'} {path}: {e}") from e

def _stage_settings(path: Path, document: TOMLDocument) -> str:
    try:
        return stage_private_bytes(str(path), document.as_string().encode())
    except OSError as error:
        raise CodexSettingsError(f"Could not stage Codex settings at {path}; no settings were changed") from error

def _commit(path: Path, staged: str | None, commit: Callable[[str, str], None]) -> None:
    if staged is None:
        path.unlink(missing_ok=True)
    else:
        commit(staged, str(path))

def commit_staged_json(staged: str, path: str) -> None:
    """Move a staged file into place, replacing whatever is there in one step"""
    try:
        os.replace(staged, path)
    except OSError:
        Path(staged).unlink(missing_ok=True)
        raise

def discard_staged_json(staged: str) -> None:
    """Throw a staged file away when the change it was part of is abandoned"""
    Path(staged).unlink(missing_ok=True)
